#!/usr/bin/env python3
# luxarch:shared-machine-argv hook v1 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""The paths a program's argv writes, for the shared-machine hook: GNU-style option parsing (an option
anywhere among the operands, a long option abbreviated as getopt allows) and, per program, which
operand or option value is a file it writes (`cp`, `mv`, `install`, `ln`, `sed -i`, `perl -i`,
`rsync`, `git clone|init|worktree`, `mktemp`, `tar`, `unzip`, `curl`, `wget`).

Python 3.9 and the standard library only, like the hook that loads it.
"""

from __future__ import annotations

import os
import re
from collections.abc import Callable

from _cmdtext import SimpleCommand


def canon(name: str, known: set[str]) -> str:
    """A GNU long option as given, or the one option it abbreviates (`--targ` is
    `--target-directory`): getopt takes any unambiguous prefix."""
    if name in known or len(name) < 3:
        return name
    hits = [o for o in known if o.startswith(name)]
    return hits[0] if len(hits) == 1 else name


def split_opts(
    args: list[str],
    value_short: str,
    value_long: set[str],
    flag_long: frozenset[str] = frozenset(),
) -> tuple[dict[str, list[str]], list[str]]:
    """GNU-style options, anywhere among the operands: {option: [values]} and the operands
    (everything after `--` included). `flag_long` names long options that take no value, so an
    abbreviation is matched against every option the program has."""
    opts: dict[str, list[str]] = {}
    ops: list[str] = []
    i = 0
    while i < len(args):
        w = args[i]
        i += 1
        if w == "--":
            ops += args[i:]
            break
        if w.startswith("--"):
            name, eq, val = w.partition("=")
            name = canon(name, value_long | flag_long)
            if not eq and name in value_long and i < len(args):
                val, i = args[i], i + 1
            opts.setdefault(name, []).append(val)
        elif w.startswith("-") and len(w) > 1:
            for k, ch in enumerate(w[1:], 1):
                if ch in value_short:
                    val = w[k + 1 :]
                    if not val and i < len(args):
                        val, i = args[i], i + 1
                    opts.setdefault("-" + ch, []).append(val)
                    break
                opts.setdefault("-" + ch, []).append("")
        else:
            ops.append(w)
    return opts, ops


def _has(opts: dict[str, list[str]], *names: str) -> bool:
    return any(n in opts for n in names)


def vals(opts: dict[str, list[str]], *names: str) -> list[str]:
    return [v for n in names for v in opts.get(n, [])]


# Per program: (short options with a value, long options with a value, long options without one).
# `--backup[=C]` and `--context[=C]` take a value only after `=`.
_COREUTILS = {
    "cp": ("St", {"--suffix", "--target-directory", "--sparse", "--no-preserve"},
           {"--backup", "--context", "--strip-trailing-slashes", "--preserve", "--reflink",
            "--recursive", "--force", "--archive", "--parents", "--update", "--link",
            "--symbolic-link", "--no-target-directory", "--no-clobber", "--interactive"}),
    "mv": ("St", {"--suffix", "--target-directory"},
           {"--backup", "--context", "--strip-trailing-slashes", "--force", "--update",
            "--no-target-directory", "--no-clobber", "--interactive", "--exchange"}),
    "ln": ("St", {"--suffix", "--target-directory"},
           {"--backup", "--symbolic", "--force", "--relative", "--no-dereference", "--logical",
            "--physical", "--no-target-directory", "--interactive", "--verbose"}),
    "install": ("gmoSt", {"--suffix", "--target-directory", "--mode", "--owner", "--group",
                          "--strip-program"},
                {"--backup", "--context", "--strip", "--directory", "--compare",
                 "--preserve-timestamps", "--no-target-directory", "--verbose"}),
    "mkdir": ("m", {"--mode"}, {"--context", "--parents", "--verbose"}),
    "touch": ("rdt", {"--reference", "--date", "--time"},
              {"--no-create", "--no-dereference"}),
    "truncate": ("sr", {"--size", "--reference"}, {"--no-create", "--io-blocks"}),
}  # fmt: skip


def _copy_targets(base: str, args: list[str]) -> list[str]:
    short, value_long, flag_long = _COREUTILS[base]
    opts, ops = split_opts(args, short, value_long, frozenset(flag_long))
    out = vals(opts, "-t", "--target-directory")
    if base == "install" and _has(opts, "-d", "--directory"):
        return out + ops
    if out:
        return out
    if len(ops) >= 2:
        out.append(ops[-1])
    elif base == "ln" and ops:
        out.append(".")  # `ln -s target`: the link lands in the current directory
    return out


def _sed_files(args: list[str]) -> list[str]:
    inplace = script = False
    files: list[str] = []
    i = 0
    while i < len(args):
        w = args[i]
        i += 1
        if w.startswith("--"):
            name, eq, _v = w.partition("=")
            name = canon(name, {"--in-place", "--expression", "--file", "--quiet",
                                 "--silent", "--regexp-extended", "--separate", "--sandbox",
                                 "--null-data", "--posix", "--debug", "--follow-symlinks",
                                 "--line-length", "--unbuffered"})  # fmt: skip
            inplace = inplace or name == "--in-place"
            if name in ("--expression", "--file"):
                script = True
                i += 0 if eq else 1
            elif name == "--line-length" and not eq:
                i += 1
        elif w.startswith("-") and len(w) > 1:
            for k, ch in enumerate(w[1:], 1):
                if ch == "i":
                    inplace = True
                    if k == len(w) - 1 and i < len(args) and args[i] == "":
                        i += 1  # BSD `-i ''`
                    break
                if ch in "efl":
                    script = script or ch != "l"
                    i += 0 if k < len(w) - 1 else 1
                    break
        elif not script:
            script = True
        else:
            files.append(w)
    return files if inplace else []


def _perl_files(args: list[str]) -> list[str]:
    """The files `perl -i` edits: the operands after the script. A switch cluster is read switch by
    switch (`-0pi`, `-l0pi`): `-I`, `-M`, `-m`, `-x`, `-C`, `-d`, `-D` and `-F` take the rest of
    their word, so the `i` in `-Ilib` or `-Fi` is not `-i`; a script file ends perl's switches."""
    inplace = script = False
    files: list[str] = []
    i = 0
    while i < len(args):
        w = args[i]
        i += 1
        if w == "--":
            files += args[i:] if script else args[i + 1 :]
            break
        if w.startswith("-") and len(w) > 1:
            k = 1
            while k < len(w):
                ch = w[k]
                k += 1
                if ch == "i":
                    inplace = True
                    break  # the rest of the word is the backup suffix
                if ch in "eE":
                    script = True
                    i += 1 if k == len(w) else 0
                    break
                if ch in "IMmxCdDF":
                    break
                if ch in "0l":
                    while k < len(w) and w[k] in "0123456789abcdefABCDEFx":
                        k += 1
            continue
        if not script:
            files += args[i:]  # a script file: every word after it is its argument
            break
        files.append(w)
    return files if inplace else []


