def _rsync_dest(args: list[str]) -> list[str]:
    opts, ops = split_opts(args, "TBefM", _RSYNC_VALUE, _RSYNC_FLAGS)
    out = vals(opts, "--partial-dir", "--backup-dir", "--temp-dir", "-T", "--log-file",
                "--write-batch", "--only-write-batch")  # fmt: skip
    if len(ops) >= 2:
        dest = ops[-1]
        remote = dest.startswith("rsync://") or re.match(r"^[^/]*:", dest)
        out += [] if remote else [dest]
    return out


_CLONE_VALUE = {"--origin", "--branch", "--upload-pack", "--template", "--reference",
                "--reference-if-able", "--separate-git-dir", "--depth", "--shallow-since",
                "--shallow-exclude", "--config", "--server-option", "--jobs", "--filter",
                "--bundle-uri", "--ref-format", "--revision"}  # fmt: skip


_INIT_VALUE = {"--template", "--separate-git-dir", "--object-format", "--ref-format",
               "--initial-branch"}  # fmt: skip


_INIT_FLAGS = frozenset(
    {"--shared", "--bare", "--quiet"}
)  # `--shared[=perm]`: a value only after `=`


_GIT_GLOBAL_VALUE = {
    "-C",
    "-c",
    "--git-dir",
    "--work-tree",
    "--namespace",
    "--config-env",
}


def _git_targets(args: list[str], env: dict[str, str]) -> list[str]:
    """What `git clone`, `git init` and `git worktree add|move` create, read from `git -C`'s
    directory; a repository `init` makes at `--git-dir` or `$GIT_DIR` too."""
    i, gcwd, git_dir = 0, "", env.get("GIT_DIR", "")
    while i < len(args) and args[i].startswith("-"):
        w = args[i]
        name, eq, val = w.partition("=")
        if name in _GIT_GLOBAL_VALUE and not eq:
            val = args[i + 1] if i + 1 < len(args) else ""
        if name == "-C":
            gcwd = os.path.join(gcwd, val)
        elif name == "--git-dir":
            git_dir = val
        i += 2 if (name in _GIT_GLOBAL_VALUE and not eq) else 1
    sub, rest = (args[i], args[i + 1 :]) if i < len(args) else ("", [])
    out: list[str] = []
    if sub == "clone":
        opts, ops = split_opts(rest, "obucj", _CLONE_VALUE)
        out = (ops[1:2] or ["."]) + vals(opts, "--separate-git-dir")
    elif sub == "init":
        opts, ops = split_opts(rest, "b", _INIT_VALUE, _INIT_FLAGS)
        out = (ops[:1] or ["."]) + vals(opts, "--separate-git-dir")
        out += [git_dir] if git_dir else []
    elif sub == "worktree" and rest[:1] == ["add"]:
        _o, ops = split_opts(rest[1:], "bB", {"--reason"})
        out = ops[:1]
    elif sub == "worktree" and rest[:1] == ["move"]:
        _o, ops = split_opts(rest[1:], "", set())
        out = ops[1:2]
    if not gcwd:
        return out
    return [w if w.startswith(("/", "~", "$")) else os.path.join(gcwd, w) for w in out]


def _mktemp_target(args: list[str], values: dict[str, str]) -> list[str]:
    opts, ops = split_opts(
        args,
        "p",
        {"--suffix"},
        frozenset({"--tmpdir", "--dry-run", "--directory", "--quiet"}),
    )
    if _has(opts, "-u", "--dry-run"):
        return []
    tmpdir = values.get("TMPDIR") or os.environ.get("TMPDIR") or "/tmp"
    given = [v for v in vals(opts, "-p", "--tmpdir") if v]
    template = ops[0] if ops else ""
    if template.startswith("/"):
        return [template]
    if given:
        return [os.path.join(given[0], template or "x")]
    if not template or _has(opts, "-t", "--tmpdir"):
        return [os.path.join(tmpdir, template or "tmp.x")]
    return [template]


_TAR_VALUE_SHORT = "fCTXbgLNVHK"


_TAR_VALUE_LONG = {"--file", "--directory", "--files-from", "--exclude-from", "--format",
                   "--blocking-factor", "--listed-incremental", "--exclude"}  # fmt: skip


_TAR_MODES = frozenset({"--extract", "--get", "--create", "--append", "--update", "--delete",
                        "--list", "--diff", "--compare", "--concatenate", "--catenate"})  # fmt: skip


def _tar_targets(args: list[str]) -> list[str]:
    """Where `tar` writes: the directory it extracts into, or the archive it creates or changes."""
    if args and not args[0].startswith("-"):
        # The old bundled form: each letter is an option, and each that takes a value takes the
        # next word, in order (`tar xfC a.tar /usr`, `tar Cxf /usr a.tar`).
        words, new = args[1:], []
        for ch in args[0]:
            new.append("-" + ch)
            if ch in _TAR_VALUE_SHORT and words:
                new.append(words.pop(0))
        args = new + words
    opts, _ops = split_opts(args, _TAR_VALUE_SHORT, _TAR_VALUE_LONG, _TAR_MODES)
    if _has(opts, "-x", "--extract", "--get"):
        return vals(opts, "-C", "--directory") or ["."]
    if _has(opts, "-c", "--create", "-r", "--append", "-u", "--update", "-A", "--concatenate",
            "--catenate", "--delete"):  # fmt: skip
        return [f for f in vals(opts, "-f", "--file") if f != "-"]
    return []


def _unzip_targets(args: list[str]) -> list[str]:
    """Where `unzip` extracts: `-d DIR` (or `-dDIR`, `-qd DIR`), else the current directory."""
    out: list[str] = []
    for k, w in enumerate(args):
        if w.startswith("-") and len(w) > 1:
            d = w.find("d")
            if set(w[1 : d if d > 0 else None]) & set("ltvpZz"):
                return []  # lists, tests or prints: writes nothing
            if d > 0:
                out.append(w[d + 1 :] or (args[k + 1] if k + 1 < len(args) else ""))
    return out or ["."]


