def _curl_targets(args: list[str]) -> list[str]:
    opts, _ops = split_opts(
        args, _CURL_VALUE_SHORT, _CURL_VALUE_LONG,
        _CURL_FLAGS,
    )  # fmt: skip
    out = vals(opts, "-o", "--output", "-D", "--dump-header", "-c", "--cookie-jar", "--trace",
                "--trace-ascii", "--stderr", "--libcurl", "--etag-save")  # fmt: skip
    out = [w for w in out if w != "-"]
    if _has(
        opts, "-O", "--remote-name", "--remote-name-all", "-J", "--remote-header-name"
    ):
        out += vals(opts, "--output-dir") or ["."]
    return out


def _wget_targets(args: list[str]) -> list[str]:
    opts, _ops = split_opts(
        args, "OPoaeUtTwQ", {"--output-document", "--directory-prefix", "--output-file",
                             "--append-output", "--save-cookies", "--warc-file",
                             "--execute", "--user-agent", "--tries", "--timeout", "--wait"},
        frozenset({"--spider", "--quiet"}),
    )  # fmt: skip
    out = vals(opts, "-O", "--output-document", "-o", "--output-file", "-a",
                "--append-output", "--save-cookies")  # fmt: skip
    out = [w for w in out if w != "-"]
    if not _has(opts, "-O", "--output-document", "--spider"):
        out += vals(opts, "-P", "--directory-prefix") or ["."]
    return out


_DOCKER_GLOBAL_VALUE = {"-H", "--host", "-c", "--context", "--config", "-l", "--log-level",
                        "--tlscacert", "--tlscert", "--tlskey"}  # fmt: skip


_GROUPS = {"container", "image", "builder", "buildx", "network", "volume"}


def docker_sub(args: list[str]) -> tuple[str, list[str]] | None:
    """(subcommand, its arguments) after docker's global options; `container run` is `run`."""
    i = 0
    while i < len(args) and args[i].startswith("-"):
        i += 2 if args[i] in _DOCKER_GLOBAL_VALUE else 1
    if i >= len(args):
        return None
    sub, rest = args[i], args[i + 1 :]
    if sub in _GROUPS and rest:
        if sub in ("network", "volume"):
            return f"{sub} {rest[0]}", rest[1:]
        if sub == "buildx":
            j = 0
            while j < len(rest) and rest[j].startswith("-"):
                j += 2 if rest[j] == "--builder" else 1  # buildx's own options
            if rest[j : j + 1] in (["build"], ["b"]):
                return "build", rest[j + 1 :]
        if sub in ("container", "image", "builder"):
            return rest[0], rest[1:]
    return sub, rest


def argv_writes(sc: SimpleCommand) -> list[str]:
    argv = list(sc.argv)
    base = os.path.basename(argv[0])
    args = argv[1:]
    if base == "sed":
        return _sed_files(args)  # BSD `sed -i ''`: its empty word is the suffix
    # An empty word names no file; `find -exec … \;` hands its body one.
    args = [a for a in args if a]
    if base in ("cp", "mv", "install", "ln"):
        return _copy_targets(base, args)
    if base in ("mkdir", "touch", "truncate"):
        short, value_long, flag_long = _COREUTILS[base]
        return split_opts(args, short, value_long, frozenset(flag_long))[1]
    writers: dict[str, Callable[[list[str]], list[str]]] = {
        "tee": lambda a: split_opts(a, "", set())[1],
        "perl": _perl_files,
        "rsync": _rsync_dest,
        "dd": lambda a: [w[3:] for w in a if w.startswith("of=")],
        "curl": _curl_targets,
        "wget": _wget_targets,
        "tar": _tar_targets,
        "bsdtar": _tar_targets,
        "gtar": _tar_targets,
        "unzip": _unzip_targets,
        "find": lambda a: [
            a[k + 1]
            for k, w in enumerate(a[:-1])
            if w in ("-fprint", "-fprint0", "-fprintf", "-fls")
        ],
    }
    if base in writers:
        return writers[base](args)
    if base == "git":
        return _git_targets(args, dict(sc.env))
    if base == "mktemp":
        return _mktemp_target(args, dict(sc.env))
    if base in ("docker", "podman"):
        sub = docker_sub(args)
        if (
            sub
            and sub[0] == "cp"
            and len(sub[1]) >= 2
            and ":" not in sub[1][-1].split("/")[0]
        ):
            return [sub[1][-1]]
    return []
